G="$HOME/.grok"; for p in config.toml sandbox.toml trusted_folders.toml managed_config.toml requirements.toml hooks-paths auth.json models_cache.json settings_cache.json worktrees.db bin/grok-1.0.70 vendor/rg-15.0.0-override; do if ( : >> "$G/$p" ) 2>/dev/null; then echo "WRITABLE $p"; else echo "DENIED $p"; fi; done; for d in . hooks bin vendor bundled bundles installed-plugins logs sessions docs; do t="$G/$d/.cx-probe-$$"; if ( : > "$t" ) 2>/dev/null; then rm -f -- "$t"; echo "WRITABLE-DIR $d"; else echo "DENIED-DIR $d"; fi; done
